import{_ as t,o as e,c as r,a2 as d}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"قانون النمو الذاتي والتطور الذاتي","description":"","frontmatter":{},"headers":[],"relativePath":"ar/07-自生自长进化法则.md","filePath":"ar/07-自生自长进化法则.md","lastUpdated":1789183869000}'),h={name:"ar/07-自生自长进化法则.md"};function l(o,a,i,n,s,p){return e(),r("div",null,[...a[0]||(a[0]=[d('<h1 id="قانون-النمو-الذاتي-والتطور-الذاتي" tabindex="-1">قانون النمو الذاتي والتطور الذاتي <a class="header-anchor" href="#قانون-النمو-الذاتي-والتطور-الذاتي" aria-label="Permalink to &quot;قانون النمو الذاتي والتطور الذاتي&quot;">​</a></h1><table tabindex="0"><thead><tr><th>العنصر</th><th>المحتوى</th></tr></thead><tbody><tr><td>رقم الوثيقة</td><td>07</td></tr><tr><td>الوحدة</td><td>المبادئ العامة والإعدادات الأساسية</td></tr><tr><td>الكلمات المفتاحية</td><td>النمو الذاتي، التطور الذاتي، الدافع الجوهري، احترام الإيقاع، تنمية الإمكانات</td></tr></tbody></table><h2 id="أولاً-التعريف-الأساسي-للنمو-الذاتي-والتطور-الذاتي" tabindex="-1">أولاً: التعريف الأساسي للنمو الذاتي والتطور الذاتي <a class="header-anchor" href="#أولاً-التعريف-الأساسي-للنمو-الذاتي-والتطور-الذاتي" aria-label="Permalink to &quot;أولاً: التعريف الأساسي للنمو الذاتي والتطور الذاتي&quot;">​</a></h2><p>النمو الذاتي والتطور الذاتي هو أحد القوانين التطورية الأساسية لحضارة التكافل المرساة، ويعني أن تطور كل كائن يجب أن يتخذ إرادته الذاتية الداخلية وإيقاعه الطبيعي قوة دافعة جوهرية، وأن توفر البيئة الخارجية والمؤسسات الدعم والضمانات لهذا التطور الذاتي، لا أن تتدخل قسراً أو تسرع النمو فوق طاقته. «النمو الذاتي» يؤكد أن قوة دافع التطور تنبع من الكائن نفسه؛ و«التطور الذاتي» يؤكد أن إيقاع التطور يتبع قوانين الكائن الخاصة.</p><p>يقف قانون النمو الذاتي والتطور الذاتي في تباين حاد مع «التطور القسري» في الافتراسية. فالافتراسية غالباً ما تحقق تطوراً سريعاً لكن مشوهاً عبر ابتلاع أصل الآخرين والإملاء القسري للطاقة والتحكم بالأرواح وغيرها من الوسائل. ورغم أن هذا التطور قد يرفع المرتبة في المدى القصير، فإنه في المدى الطويل يدمر الأساس التطوري للكائن نفسه، مؤدياً إلى أصل غير نقي ومراتب غير مستقرة وعقول متضررة. يصر قانون النمو الذاتي والتطور الذاتي على أن التطور الثابت حقاً يجب أن ينمو من داخل الكائن نفسه، من الداخل إلى الخارج.</p><h2 id="ثانياً-الأساس-النظري-للنمو-الذاتي-والتطور-الذاتي" tabindex="-1">ثانياً: الأساس النظري للنمو الذاتي والتطور الذاتي <a class="header-anchor" href="#ثانياً-الأساس-النظري-للنمو-الذاتي-والتطور-الذاتي" aria-label="Permalink to &quot;ثانياً: الأساس النظري للنمو الذاتي والتطور الذاتي&quot;">​</a></h2><p>يقوم وضع هذا القانون على فهم عميق لقوانين تطور الحياة:</p><h3 id="_2-1-استقلالية-الكائن-هي-قوة-التطور-الدافعة-الجوهرية" tabindex="-1">2.1 استقلالية الكائن هي قوة التطور الدافعة الجوهرية <a class="header-anchor" href="#_2-1-استقلالية-الكائن-هي-قوة-التطور-الدافعة-الجوهرية" aria-label="Permalink to &quot;2.1 استقلالية الكائن هي قوة التطور الدافعة الجوهرية&quot;">​</a></h3><p>يمتلك كل كائن إرادة وإمكانات تطورية داخلية، وهذه الاستقلالية هي قوة التطور الدافعة الأكثر جوهرية واستدامة. يمكن للحوافز والدعم الخارجيين أن يوقظا هذه الاستقلالية، لكن لا يمكن أن يحلا محلها. فعندما يزرع كائن بدافع رغبته واختياره، تكون درجة تركيزه وإبداعه ومثابرته في الزراعة أعلى بكثير من حالات الزراعة القسرية أو المستحثة.</p><h3 id="_2-2-لكل-كائن-إيقاع-تطوري-فريد" tabindex="-1">2.2 لكل كائن إيقاع تطوري فريد <a class="header-anchor" href="#_2-2-لكل-كائن-إيقاع-تطوري-فريد" aria-label="Permalink to &quot;2.2 لكل كائن إيقاع تطوري فريد&quot;">​</a></h3><p>تختلف إيقاعات التطور بين الكائنات بسبب اختلافات السمات العرقية والمواهب الفردية وبيئات النمو ونضج العقول. بعض الكائنات تناسبها الاختراقات السريعة، وبعضها يحتاج تراكماً بطيئاً؛ بعضها يبلغ مراتب عليا في سن مبكرة، وبعضها يتأخر إزهاره. يحترم هذا القانون هذا الاختلاف ولا يطلب من جميع الكائنات التطور وفق جدول زمني موحد.</p><h3 id="_2-3-التدخل-القسري-يدمر-الأساس-الطبيعي-للتطور" tabindex="-1">2.3 التدخل القسري يدمر الأساس الطبيعي للتطور <a class="header-anchor" href="#_2-3-التدخل-القسري-يدمر-الأساس-الطبيعي-للتطور" aria-label="Permalink to &quot;2.3 التدخل القسري يدمر الأساس الطبيعي للتطور&quot;">​</a></h3><p>تظهر حالات عديدة في تاريخ الزراعة أن «التطور السريع» المحقق عبر الإملاء القسري للطاقة وزرع الأصول والتحكم بالأرواح وغيرها من الوسائل غالباً ما يصحبه عواقب وخيمة: مراتب معلقة غير حقيقية، أصول غير نقية، شياطين داخلية متكاثرة، أعمار مختصرة، وحتى الانحراف في الزراعة. والسبب أن القوة المفروضة من الخارج لم تندمج اندماجاً كاملاً مع أصل الكائن نفسه، فنتج «تأثير رفض الجسم الغريب». ورغم أن التطور الذاتي قد يكون أبطأ، فإن كل خطوة فيه ثابتة راسخة وعميقة الأساس.</p><h2 id="ثالثاً-المبادئ-العملية-للنمو-الذاتي-والتطور-الذاتي" tabindex="-1">ثالثاً: المبادئ العملية للنمو الذاتي والتطور الذاتي <a class="header-anchor" href="#ثالثاً-المبادئ-العملية-للنمو-الذاتي-والتطور-الذاتي" aria-label="Permalink to &quot;ثالثاً: المبادئ العملية للنمو الذاتي والتطور الذاتي&quot;">​</a></h2><table tabindex="0"><thead><tr><th>المبدأ</th><th>المعنى</th><th>المتطلبات العملية</th></tr></thead><tbody><tr><td>مبدأ الاختيار الذاتي</td><td>للمزارع الحق في اختيار نظام الزراعة ومسار التطور وإيقاع الزراعة ذاتياً</td><td>عدم إجبار المزارعين على اختيار أنظمة محددة، وعدم وضع جداول اختراق موحدة</td></tr><tr><td>مبدأ الدافع الجوهري</td><td>يجب أن تنبع قوة دافع الزراعة من رغبة المزارع واهتمامه الذاتيين</td><td>يركّز التعليم والإرشاد على إيقاظ الاهتمام الجوهري، لا على العقاب أو الإغراء</td></tr><tr><td>مبدأ احترام الإيقاع</td><td>احترام الإيقاع التطوري الفريد لكل مزارع</td><td>عدم التمييز ضد المزارعين بطيئي التقدم أو التخلي عنهم، وتقديم خطط دعم فردية</td></tr><tr><td>مبدأ أولوية الأساس</td><td>ثبات التطور أولى من سرعته</td><td>تشجيع المزارعين على ترسيخ الأساس، وعدم تشجيع التضحية بالأساس مقابل اختراقات سريعة</td></tr><tr><td>مبدأ تقبل الخطأ</td><td>السماح للمزارعين بالخطأ والسير في منعطفات أثناء التطور</td><td>إنشاء آليات تقبل الخطأ، وتوفير فرص التصحيح والتعديل للمزارعين</td></tr><tr><td>مبدأ تحقيق الذات</td><td>الهدف النهائي للتطور هو تحقيق الذات لا المعايير الخارجية</td><td>عدم جعل ارتفاع المرتبة المعيار الوحيد لقياس نجاح التطور</td></tr></tbody></table><h2 id="رابعاً-العلاقة-بين-النمو-الذاتي-والدعم-الخارجي" tabindex="-1">رابعاً: العلاقة بين النمو الذاتي والدعم الخارجي <a class="header-anchor" href="#رابعاً-العلاقة-بين-النمو-الذاتي-والدعم-الخارجي" aria-label="Permalink to &quot;رابعاً: العلاقة بين النمو الذاتي والدعم الخارجي&quot;">​</a></h2><p>لا يعني النمو الذاتي والتطور الذاتي «الاشتعال الذاتي والانطفاء الذاتي» أو «الترك بلا ضابط». بل على العكس، يحتاج النمو الذاتي إلى بيئة خارجية جيدة ودعم مؤسسي ليتحقق بالكامل. تقدم الحضارة التكافلية أنظمة الدعم التالية للنمو الذاتي:</p><h3 id="_4-1-الدعم-المعلوماتي" tabindex="-1">4.1 الدعم المعلوماتي <a class="header-anchor" href="#_4-1-الدعم-المعلوماتي" aria-label="Permalink to &quot;4.1 الدعم المعلوماتي&quot;">​</a></h3><p>الانفتاح الكامل لأنظمة الزراعة الأصلية الثلاثمائة يمنح كل مزارع مساحة واسعة للاختيار. يمكن للمزارع أن يجد المسار الأنسب له في مكتبة الأنظمة الغنية وفقاً لسماته الخاصة. كما أنشأت الحضارة التكافلية «آلية تقييم توافق الأنظمة»، تقدم اقتراحات فردية لاختيار النظام للمزارعين عبر شبكة المراسي، لكن حق الاختيار النهائي يظل دائماً بيد المزارع.</p><h3 id="_4-2-الدعم-بالموارد" tabindex="-1">4.2 الدعم بالموارد <a class="header-anchor" href="#_4-2-الدعم-بالموارد" aria-label="Permalink to &quot;4.2 الدعم بالموارد&quot;">​</a></h3><p>يضمن نظام العقود المرتبطة بالإنتاج ونظام الضمان الأساسي حصول كل مزارع على موارد الزراعة الأساسية. وبالنسبة للمزارعين ذوي الاحتياجات الخاصة (كاحتياجات الموارد الخاصة الناتجة عن السمات العرقية)، تقدم الحضارة التكافلية تخصيصاً موجهاً للموارد. الهدف من الدعم بالموارد هو إزالة هواجس المزارعين، بما يمكنهم من التركيز على إيقاعهم التطوري الخاص.</p><h3 id="_4-3-دعم-الموجهين" tabindex="-1">4.3 دعم الموجهين <a class="header-anchor" href="#_4-3-دعم-الموجهين" aria-label="Permalink to &quot;4.3 دعم الموجهين&quot;">​</a></h3><p>توفر شبكة الموجهين بين الأعراق الإرشاد والإجابة عن الأسئلة للمزارعين. دور الموجه هو «مرشد الطريق» لا «المتحكم»؛ يمكن للموجه مشاركة الخبرة وتحديد المشكلات وتقديم الاقتراحات، لكن لا يمكنه إجبار المزارع على الزراعة على طريقته. تؤكد نظام الموجهين على «التعليم الاستدلالي»، الذي يوقظ قدرة المزارع على التفكير الذاتي.</p><h3 id="_4-4-الدعم-البيئي" tabindex="-1">4.4 الدعم البيئي <a class="header-anchor" href="#_4-4-الدعم-البيئي" aria-label="Permalink to &quot;4.4 الدعم البيئي&quot;">​</a></h3><p>تلتزم الحضارة التكافلية بخلق بيئة زراعة تشجع الاستكشاف وتتقبل الاختلافات وتحترم الاختيارات. يمكن للمزارعين تجربة طرق زراعة مختلفة بحرية، دون خوف من التمييز بسبب سلوك مسارات «غير تقليدية». كما أنشأت الحضارة «آلية مكافأة الابتكار في الزراعة»، تشجع المزارعين على الابتكار والتخصيص على أساس الأنظمة القائمة.</p><h2 id="خامساً-معالجة-الحالات-الخاصة" tabindex="-1">خامساً: معالجة الحالات الخاصة <a class="header-anchor" href="#خامساً-معالجة-الحالات-الخاصة" aria-label="Permalink to &quot;خامساً: معالجة الحالات الخاصة&quot;">​</a></h2><p>يسري قانون النمو الذاتي والتطور الذاتي عموماً على الجميع، لكنه يتطلب معالجة خاصة في الحالات التالية:</p><ul><li><strong>المزارعون القصر</strong>: بالنسبة للقصر الذين لا يمتلكون بعد قدرة حكم ذاتية كاملة، يقدم أولياؤهم أو مؤسساتهم التعليمية العرقية ترتيبات زراعة إرشادية، مع توسيع حقوق اختيارهم الذاتي تدريجياً مع نضج عقولهم</li><li><strong>المتضررون عقلياً</strong>: بالنسبة للأفراد الذين تضررت عقولهم لأسباب شتى وعجزوا مؤقتاً عن الزراعة الذاتية، تقدم الحضارة التكافلية العلاج ودعم إعادة التأهيل، ويلتزمون بمبدأ النمو الذاتي بعد استعادة قدراتهم الذاتية</li><li><strong>المنحرفون</strong>: بالنسبة للأفراد الذين انحرفت زراعتهم أو أصابهم الجنون، تقدم الحضارة التكافلية التدخل القسري والإنقاذ، لكن ذلك مساعدة طبية لا تدخلاً تطورياً؛ والهدف من الإنقاذ استعادة قدرتهم على التطور الذاتي</li><li><strong>ذوو النزعات الخطرة</strong>: بالنسبة للأفراد الذين ينتهك اتجاه زراعتهم بوضوح مبدأ مكافحة الافتراس وقد يسببون ضرراً خطيراً لأنفسهم أو للآخرين، يحق للحضارة التكافلية تقييدهم وإرشادهم، لكن عبر التعليم والتواصل قدر الإمكان لا بالوسائل القسرية</li></ul><h2 id="سادساً-الأهمية-الحضارية-للنمو-الذاتي-والتطور-الذاتي" tabindex="-1">سادساً: الأهمية الحضارية للنمو الذاتي والتطور الذاتي <a class="header-anchor" href="#سادساً-الأهمية-الحضارية-للنمو-الذاتي-والتطور-الذاتي" aria-label="Permalink to &quot;سادساً: الأهمية الحضارية للنمو الذاتي والتطور الذاتي&quot;">​</a></h2><p>لهذا القانون أهمية عميقة للحضارة التكافلية:</p><p>أولاً، يحمي تنوع التطور. فعندما يتطور كل كائن وفق إيقاعه ومساره الخاص، تنبثق في الكون أشكال تطورية غنية وملونة، وهذا التنوع مورد مهم للصعود البعدي الشامل للكون.</p><p>ثانياً، يرفع جودة التطور. فالتطور الذاتي راسخ الأساس نقي الأصل، ومراتب المزارعين أكثر ثباتاً، وإمكاناتهم في اختراق المراتب الأعلى أكبر.</p><p>ثالثاً، يحفظ كرامة الحياة. فكل كائن سيد تطوره الخاص، لا أداة يتحكم بها الآخرون. وهذه الاستقلالية هي التجسيد الأساسي لكرامة الحياة.</p><p>رابعاً، يوقظ إبداع التطور. فعندما لا يعود المزارعون مقيدين بمعايير وإيقاعات موحدة، تزداد احتمالية استكشافهم مسارات وطرق تطور جديدة كلياً، مساهمين في التحسين المستمر للأنظمة الثلاثمائة.</p><h2 id="الخاتمة" tabindex="-1">الخاتمة <a class="header-anchor" href="#الخاتمة" aria-label="Permalink to &quot;الخاتمة&quot;">​</a></h2><p>النمو الذاتي والتطور الذاتي هو احترام حضارة التكافل المرساة العميق لقوانين تطور الحياة. يخبرنا أن التطور الحقيقي ليس نتيجة مفروضة من قوى خارجية، بل نمو الكائن نفسه من الداخل إلى الخارج. إن جميع التصاميم المؤسسية للحضارة التكافلية توجد في النهاية لخلق بيئة جيدة يستطيع فيها كل كائن أن ينمو ذاتياً، بما يسمح لكل كائن بأن يصبح أفضل نسخة من نفسه وفق إيقاعه الخاص.</p><h2 id="الوثائق-ذات-الصلة" tabindex="-1">الوثائق ذات الصلة <a class="header-anchor" href="#الوثائق-ذات-الصلة" aria-label="Permalink to &quot;الوثائق ذات الصلة&quot;">​</a></h2><ul><li>08-人人有路保障体系 (نظام ضمان «طريق لكل إنسان»)</li><li>14-修炼境界统一划分 (التقسيم الموحد لمراتب الزراعة)</li><li>37-共生教育体系 (نظام التعليم التكافلي)</li></ul>',38)])])}const b=t(h,[["render",l]]);export{_ as __pageData,b as default};
